def select_tree(current_user_properties, node_name, Session):
    url_lists_node = None
    acls_node = None
    roles_node = None
    users_node = None

    current_user_permissions = current_user_properties['user_permissions']

    if next((item for item in current_user_permissions if item['permissionName'] == 'ViewSettings'), None) != None:
        if node_name in ['root', 'urllists']:
            url_lists_node = _get_url_lists(Session)

        if node_name in ['root', 'acls']:
            acls_node = _get_acls(Session)

    if next((item for item in current_user_permissions if item['permissionName'] == 'ViewPermissions'), None) != None:
        if node_name in ['root', 'roles']:
            roles_node = _get_roles(Session)

    if node_name in ['root']:
        users_node = _get_user_tree(current_user_properties, Session)

    if node_name == 'root':
        children_list = []

        if url_lists_node is not None:
            children_list.append(url_lists_node)

        if acls_node is not None:
            children_list.append(acls_node)

        if roles_node is not None:
            children_list.append(roles_node)

        if users_node is not None:
            children_list.append(users_node)

        result = {
            'success': True,
            'children': children_list
            }
    elif node_name == 'urllists':
        if next((item for item in current_user_permissions if item['permissionName'] == 'ViewSettings'), None) != None:
            result = {
                'success': True,
                'children': url_lists_node['children']
                }
        else:
            return Response('Forbidden', 403)
    elif node_name == 'acls':
        if next((item for item in current_user_permissions if item['permissionName'] == 'ViewSettings'), None) != None:
            result = {
                'success': True,
                'children': acls_node['children']
                }
        else:
            return Response('Forbidden', 403)
    elif node_name == 'roles':
        if next((item for item in current_user_permissions if item['permissionName'] == 'ViewPermissions'), None) != None:
            result = {
                'success': True,
                'children': roles_node['children']
                }
        else:
            return Response('Forbidden', 403)

    return jsonify(result)

import sys


class MergeKBs():
    def __init__(self, WNnodesFilename, WNedgesFilename, CNnodesFilename, CNedgesFilename, matchedNodesFilename, matchedEdgesFilename, matchKBs):
        self.WNnodesFilename = WNnodesFilename
        self.WNedgesFilename = WNedgesFilename
        self.CNnodesFilename = CNnodesFilename
        self.CNedgesFilename = CNedgesFilename
        self.matchedNodesFilename = matchedNodesFilename
        self.matchedEdgesFilename = matchedEdgesFilename
        self.matchedRels = []
        self.matchKBs = matchKBs

    def mergeKBs(self):
        print 'Reading WordNet nodes and edges...',
        sys.stdout.flush()
        self.WNnodesList, self.WNnodesFields, self.WNnodesTypes = self.readCSV(self.WNnodesFilename)
        self.WNrelsList, self.WNrelsFields, self.WNrelsTypes = self.readCSV(self.WNedgesFilename)
        print 'done.'

        print 'Reading ConceptNet nodes and edges...',
        sys.stdout.flush()
        self.CNnodesList, self.CNnodesFields, self.CNnodesTypes = self.readCSV(self.CNnodesFilename)
        self.CNrelsList, self.CNrelsFields, self.CNrelsTypes = self.readCSV(self.CNedgesFilename)
        print 'done.'

        print 'Adding KB source property to relationships...',
        sys.stdout.flush()
        self.addKBsourceProperty()
        print 'done.'

        print 'Creating data structures...',
        sys.stdout.flush()
        self.wn = OrderedDictionary(self.getDictFromListOfNodes(self.WNnodesList))
        self.cn = OrderedDictionary(self.getDictFromListOfNodes(self.CNnodesList))
        print 'done.'

        print 'Writing merged Nodes File...',
        sys.stdout.flush()
        self.writeCSV( self.matchedNodesFilename,
                       [self.WNnodesList, self.CNnodesList], \
                       [self.WNnodesFields, self.CNnodesFields], \
                       [self.WNnodesTypes, self.CNnodesTypes] )
        print 'done.'

        if self.matchKBs == 'match':
            print 'Matching nodes...',
            sys.stdout.flush()
            self.matchNodes()
            print 'done.'

        print 'Writing merged Edges File...',
        sys.stdout.flush()
        self.writeCSV( self.matchedEdgesFilename, \
                       [self.WNrelsList, self.CNrelsList, self.matchedRels], \
                       [self.WNrelsFields, self.CNrelsFields], \
                       [self.WNrelsTypes, self.CNrelsTypes] )
        print 'done.'


    def readCSV(self, filename):
        lines = None
        with open(filename, 'r') as f:
            lines = f.readlines()

        fields = lines[0][:-1].split('\t') # [:-1] to remove '\n'
        types = []
        for f in fields:
            t = ''
            Scolon = f.split(':')
            if len(Scolon) > 1:
                if Scolon[1] == 'int':
                    t = 'i'
                elif Scolon[1] == 'float':
                    t = 'f'
            else:
                t = 's' # string
            if '[]' in f:
                t = t + 'a' # array of
            # override for 'id:ID', ':LABEL', etc.
            if f in ['id:ID', ':LABEL', ':START_ID', ':END_ID',  ':TYPE']:
                t = 's'
            types.append(t)

        l = []
        for i in range(1, len(lines)):
            values = lines[i][:-1].split('\t') # [:-1] to remove '\n'
            name = values[0][1:-1] # removing ""

            # if name.startswith('wn/'):
            #     name = name[3:]

            n = {}
            for j in range(0, len(values)):
                if values[j] != '' and values[j] != '""':   # in that case, the value is null for that record
                    if types[j] == 'i':
                        n[fields[j]] = int(values[j])
                    elif types[j] == 'f':
                        n[fields[j]] = float(values[j])
                    elif types[j] == 's':
                        if values[j][0] == '"' and values[j][-1] == '"':
                            n[fields[j]] = values[j][1:-1] # removing ""
                        else:
                            n[fields[j]] = values[j] # Labels might have no ""...
                    elif types[j] == 'ia':
                        n[fields[j]] = [int(i) for i in values[j].split(';')]
                    elif types[j] == 'fa':
                        n[fields[j]] = [float(i) for i in values[j].split(';')]
                    elif types[j] == 'sa':
                        n[fields[j]] = values[j][1:-1].split(';')
            l.append(n)
        return l, fields, types

    # A 'KB' source property is added to relationships to make it easier to
    # calculate paths that stay within specific KBs.
    def addKBsourceProperty(self):
        self.WNrelsFields.append('KB')
        self.CNrelsFields.append('KB')
        self.WNrelsTypes.append('s')
        self.CNrelsTypes.append('s')
        for r in self.WNrelsList:
            r['KB'] = "W"
        for r in self.CNrelsList:
            r['KB'] = "C"


    def getDictFromListOfNodes(self, l):
        d = {}
        for e in l:
            d[ e['id:ID'] ] = e
        return d


    def writeCSV(self, filename, ItemsLists, ItemFields, ItemsTypes):
        matchedFields, matchedTypes = self.matchHeaders(ItemFields, ItemsTypes)

        with open(filename, 'w') as of:
            header = '\t'.join(matchedFields)
            of.write(header + '\n')

            for l in ItemsLists:
                for i in l:
                    line = ''
                    for idx, f in enumerate(matchedFields):
                        if f in i:
                            if matchedTypes[idx] in ['i', 'f']:
                                line += str(i[f])
                                #of.write(str(i[f]))
                            elif matchedTypes[idx] == 's':
                                line += '"{0}"'.format(i[f])
                                # of.write( '"{0}"'.format(i[f]) )
                            elif matchedTypes[idx] in ['ia', 'fa']:
                                line += '"{0}"'.format( ';'.join([str(j) for j in i[f]]) )
                                # of.write( '"{0}"'.format( ';'.join([str(j) for j in i[f]]) ) )
                            elif matchedTypes[idx] == 'sa':
                                line += '"{0}"'.format( ';'.join(i[f]) )
                                # of.write( '"{0}"'.format( ';'.join(i[f]) ) )
                        line += '\t'
                        #of.write('\t')
                    of.write( line[:-1] + '\n' ) # line[:-1] because there's an extra tab at the end
                    # of.write('\n')



    def matchHeaders(self, FieldsList, TypesList):
        matchedFields = []
        matchedTypes = []
        for idxFL, fl in enumerate(FieldsList):
            for idxF, f in enumerate(fl):
                if f not in matchedFields:
                    matchedFields.append(f)
                    matchedTypes.append( TypesList[idxFL][idxF] )
        return matchedFields, matchedTypes


    def addRel(self, c, w):
        self.matchedRels.append( {':START_ID':c, ':END_ID':w, ':TYPE':'KBmatch', 'KB':'M'} )


    def matchNodes(self):
        self.matchedRels = []

        matched = 0
        multiple_matched = 0
        for idx, c in enumerate(self.cn.nd):
            t = c[6:].replace('_', '+').split('/')
            if len(t) > 1:
                w = 'wn/' + t[0] + '-' + t[1]
                if t[1] == 'a':
                    if w not in self.wn.nd:
                        w = w[:-1] + 's'
                if w in self.wn.nd:
                    matched += 1
                    self.addRel(c, w)
            else:
