        self['subpages_8'] = Pixmap()
        self['subpages_9'] = Pixmap()
        self['Marker'] = Label('>')
        self.subpage = {1: self['subpages_1'],
         2: self['subpages_2'],
         3: self['subpages_3'],
         4: self['subpages_4'],
         5: self['subpages_5'],
         6: self['subpages_6'],
         7: self['subpages_7'],
         8: self['subpages_8'],
         9: self['subpages_9']}
        self.subpage_png = {1: LoadPixmap(resolveFilename(SCOPE_ACTIVE_SKIN, 'icons/rass_page1.png')),
         2: LoadPixmap(resolveFilename(SCOPE_ACTIVE_SKIN, 'icons/rass_page2.png')),
         3: LoadPixmap(resolveFilename(SCOPE_ACTIVE_SKIN, 'icons/rass_page3.png')),
         4: LoadPixmap(resolveFilename(SCOPE_ACTIVE_SKIN, 'icons/rass_page4.png'))}
        self.current_page = 0
        self.current_subpage = 0
        self.showRassPage(0, 0)
        self.onLayoutFinish.append(self.updateSubPagePixmaps)

    def updateSubPagePixmaps(self):
        service = self.session.nav.getCurrentService()
        decoder = service and service.rdsDecoder()
        if not decoder:
            print 'NO RDS DECODER in showRassPage'
        else:
            mask = decoder.getRassInteractiveMask()
            page = 1
            while page < 10:
                subpage_cnt = self.countAvailSubpages(page, mask)
                subpage = self.subpage[page]
                if subpage_cnt > 0:
                    if subpage.instance:
                        png = self.subpage_png[subpage_cnt]
                        if png:
                            subpage.instance.setPixmap(png)
                            subpage.show()
                        else:
                            print 'rass png missing'
                else:
                    subpage.hide()
                page += 1

    def recvRassInteractivePicMaskChanged(self):
        self.updateSubPagePixmaps()

    def showRassPage(self, page, subpage):
        service = self.session.nav.getCurrentService()
        decoder = service and service.rdsDecoder()
        if not decoder:
            print 'NO RDS DECODER in showRassPage'
        else:
            decoder.showRassInteractivePic(page, subpage)
            page_diff = page - self.current_page
            self.current_page = page
            if page_diff:
                current_pos = self['Marker'].getPosition()
                y = current_pos[1]
                y += page_diff * 25
                self['Marker'].setPosition(current_pos[0], y)

    def getMaskForPage(self, page, masks = None):
        if not masks:
            service = self.session.nav.getCurrentService()
            decoder = service and service.rdsDecoder()
            if not decoder:
                print 'NO RDS DECODER in getMaskForPage'
            masks = decoder.getRassInteractiveMask()
        if masks:
            mask = masks[page * 4 / 8]
            if page % 2:
                mask >>= 4
            else:
                mask &= 15
        return mask

    def countAvailSubpages(self, page, masks):
        mask = self.getMaskForPage(page, masks)
        cnt = 0
        while mask:
            if mask & 1:
                cnt += 1
            mask >>= 1

        return cnt

    def nextPage(self):
        mask = 0
        page = self.current_page
        while mask == 0:
            page += 1
            if page > 9:
                page = 0
            mask = self.getMaskForPage(page)

        self.numPressed(page)

    def prevPage(self):
        mask = 0
        page = self.current_page
        while mask == 0:
            if page > 0:
                page -= 1
            else:
                page = 9
            mask = self.getMaskForPage(page)

        self.numPressed(page)

    def nextSubPage(self):
        self.numPressed(self.current_page)

    def prevSubPage(self):
        num = self.current_page
        mask = self.getMaskForPage(num)
        cur_bit = 1 << self.current_subpage
        tmp = cur_bit
        while True:
            if tmp == 1:
                tmp = 8
            else:
                tmp >>= 1
            if tmp == cur_bit:
                return
            if mask & tmp:
                subpage = 0
                while tmp > 1:
                    subpage += 1
                    tmp >>= 1

                self.current_subpage = subpage
                self.showRassPage(num, subpage)
                return

    def numPressed(self, num):
        mask = self.getMaskForPage(num)
        if self.current_page == num:
            self.skip = 0
            cur_bit = 1 << self.current_subpage
            tmp = cur_bit
        else:
            self.skip = 1
            cur_bit = 16
            tmp = 1
        while True:
            if not self.skip:
                if tmp == 8 and cur_bit < 16:
                    tmp = 1
                else:
                    tmp <<= 1
            else:
                self.skip = 0
            if tmp == cur_bit:
                return
            if mask & tmp:
                subpage = 0
                while tmp > 1:
                    subpage += 1
                    tmp >>= 1

                self.current_subpage = subpage
                self.showRassPage(num, subpage)
                return

# Implementation of sequence elements that are composed out of pulses

# Author : W. Pfaff

# modified by: Sarwan Peiter

import numpy as np
from copy import deepcopy
import pprint
import logging


class Element:
	"""
	Implementation of a sequence element.
	Basic idea: add different pulses, and compose the actual numeric
	arrays that form the amplitudes for the hardware (typically an AWG) (includes
	discretization using clock)
	"""
	def __init__(self,name, **kw):


		self.name = name

		self.clock = kw.pop('clock', 1e9)
		self.granularity = kw.pop('granularity', 4)
		self.min_samples = kw.pop('min_samples', 960)
		self.pulsar = kw.pop('pulsar', None)
		self.ignore_offset_correction =  kw.pop('ignore_offset_correction',False)
		self.global_time = kw.pop('global_time', True)
		self.time_offset = kw.pop('time_offset', 0)

		self.ignore_delays = kw.pop('ignore_delays',False)

		# Default fixed point, used for aligning RO elements. Aligns first RO
		self.readout_fixed_point = kw.pop('readout_fixed_point', 1e-6)
		# used to track if a correction has been applied
		self.fixed_point_applied = False

		self.pulses = {}
		self._channels ={}

		self._last_added_pulse = None

		# Take clock of AWG

		if self.pulsar is not None:
			self.clock = self.pulsar.clock


			for c in self.pulsar.channels:
				chan =  self.pulsar.channels[c]
				delay = chan['delay'] if not (self.ignore_delays) else 0.
				self.define_channel(name = c, type = chan['type'], high = chan['high'],
									low = chan['low'], offset = chan['offset'], delay = delay, id = chan['id'])


	# Channel managment
	def define_channel(self, name, type = 'analog',  high = 1, low = 1,
						offset = 0, delay = 0, id = 'ch'):

		self._channels[name]= {'type': type,
							   'delay': delay,
							   'offset': offset,
							   'high': high,
							   'low': low,
							   'id': id,
							   'distorted': False}



	def get_channel_delay(self, cname):
		return self._channels[cname]['delay']


	# Auxillary functions for discretization

	def _time2sample(self,t):

		return int(t * self.clock + 0.5)

	def _sample2time(self,s):
		return s / self.clock

	def offset(self):
		"""
		Returns the smallest t0 of all pulses/channels after correcting delay
		"""

		if self.ignore_offset_correction:
			return 0

		else:
			t0s = []

			for p in self.pulses:
				for c in self.pulses[p].channels:
					t0s.append(self.pulses[p].t0() - self._channels[c]['delay'])

			return min(t0s)


	def ideal_length(self):
		"""
		Returns the nomimal length of the element before taking into account the 
		discretization using clock
		"""

		ts = []

		for p in self.pulses:
			for c in self.pulses[p].channels:
				ts.append(self.pulse_end_time(p,c))

		return max (ts)

	def pulse_end_time(self, pname, cname):
		return self.pulses[pname].end() - self._channels[cname]['delay']- \
			self.offset()

	def pulse_length(self, pname):
		return self.pulses[pname].length

	def length(self):
		"""

		Returns the actual length of the sequence, including all corrections.

		"""

		return self.samples()/self.clock


	def samples(self):
		"""
		Returns the number of samples the elements occupies
		"""

		ends = []
		for p in self.pulses:
			for c in self.pulses[p].channels:
				ends.append(self.pulse_end_sample(p,c))

		samples = max(ends) + 1

		if samples < self.min_samples:
			samples = self.min_samples

		else:
			while(samples % self.granularity > 0):
				samples += 1

		return samples


	def pulse_end_sample(self,pname,cname):
		return self.pulse_start_sample(pname,cname) + self.pulse_samples(pname) - 1

	def pulse_start_sample(self,pname,cname):
		return self._time2sample(self.pulse_start_time(pname,cname))

	def pulse_start_time(self,pname,cname):
		return self.pulses[pname].t0() - self._channels[cname]['delay'] - self.offset()


	def pulse_samples(self,pname):
		return self._time2sample(self.pulses[pname].length)



	def shift_all_pulses(self, dt):
		'''
		Shifts all pulses by a time dt, this is used for correcting the phase
		of a fixed reference.
		'''
		self.ignore_offset_correction = True
		for name, pulse in self.pulses.items():
			pulse._t0 += dt


	def _auto_pulse_name(self, base='pulse'):
		i = 0
		while base+'-'+str(i) in self.pulses:
			i += 1
		return base+'-'+str(i)




	def add(self, pulse, name=None, start=0,
			refpulse=None, refpoint='end', refpoint_new='start',
			operation_type='other',
			fixed_point_freq=None):
		'''
		Function adds a pulse to the element, there are several options to set
		where in the element the pulse is added.
		name (str)          : name used for referencing the pulse in the
							  element, if not specified generates one based on
							  the default pulse name
		start (float)       : time between refpoint and refpoint_new used to
							  define the start of the pulse
		refpulse (str)      : name of pulse used as reference for timing
		refpoint ('start'|'end'|'center') : reference point in reference
											pulse used
		refpoint_new ('start'|'end'|'center'): reference point in added
											   pulse used
		fixed_point_freq (float): if not None shifts all pulses so that
								  this pulse is at a multiple of 1/fixed_point_freq
		'''
		pulse = deepcopy(pulse)
		pulse.operation_type = operation_type
		if name is None:
			name = self._auto_pulse_name(pulse.name)

		t0 = start - pulse.start_offset
		if refpoint not in ['start', 'center', 'end']:
			raise ValueError('refpoint not recognized')

		if refpoint_new not in ['start', 'center', 'end']:
			raise ValueError('refpoint not recognized')

		if refpulse is not None:
			if refpoint is None:
				refpoint = 'end'

			if refpoint_new == 'start':
				t0 += self.pulses[refpulse].effective_stop()

				if refpoint == 'start':
					t0 -= self.pulses[refpulse].effective_length()
				elif refpoint == 'center':
					t0 -= self.pulses[refpulse].effective_length()/2.

			elif refpoint_new == 'end':
				t0 += (self.pulses[refpulse].effective_stop() -
					   pulse.effective_length())
				if refpoint == 'start':
					t0 -= self.pulses[refpulse].effective_length()
				elif refpoint == 'center':
					t0 -= self.pulses[refpulse].effective_length()/2.

			elif refpoint_new == 'center':
				t0 += (self.pulses[refpulse].effective_stop() -
					   pulse.effective_length()/2.)
				if refpoint == 'start':
					t0 -= self.pulses[refpulse].effective_length()
				elif refpoint == 'center':
					t0 -= self.pulses[refpulse].effective_length()/2.

		pulse._t0 = t0

		self.pulses[name] = pulse
		self._last_added_pulse = name
		# Shift all pulses to the fixed point for the first RO pulse encountered
		if operation_type == 'RO' and self.fixed_point_applied is False:
			time_corr = calculate_time_correction(t0, self.readout_fixed_point)
			self.shift_all_pulses(time_corr)
			self.fixed_point_applied = True
		return name


	# computing the numerical waveform
	def ideal_waveforms(self):
		wfs = {}
		tvals = np.arange(self.samples())/self.clock

		for c in self._channels:
			wfs[c] = np.zeros(self.samples()) + self._channels[c]['offset']
		# we first compute the ideal function values
		for p in self.pulses:
			psamples = self.pulse_samples(p)
			if not self.global_time:
				pulse_tvals = tvals.copy()[:psamples]
				pulsewfs = self.pulses[p].get_wfs(pulse_tvals)
			else:
				chan_tvals = {}
				for c in self.pulses[p].channels:
					idx0 = self.pulse_start_sample(p, c)
					idx1 = self.pulse_end_sample(p, c) + 1

					c_tvals = np.round(tvals.copy()[idx0:idx1] +
									   self.get_channel_delay(c) +
									   self.time_offset,
									   11) # significant digits 11
					chan_tvals[c] = c_tvals

				pulsewfs = self.pulses[p].get_wfs(chan_tvals)
			for c in self.pulses[p].channels:
				idx0 = self.pulse_start_sample(p, c)
				idx1 = self.pulse_end_sample(p, c) + 1
				wfs[c][idx0:idx1] += pulsewfs[c]

		return tvals, wfs

	def waveforms(self):
		"""
		return:
			tvals, wfs
		Returns the waveforms for all used channels.
		Trunctates/clips (channel-imposed) all values
		that are out of bounds
		"""
		tvals, wfs = self.ideal_waveforms()
		for wf in wfs:
			hi = self._channels[wf]['high']
			lo = self._channels[wf]['low']

			if self._channels[wf]['distorted'] is True:
				wfs[wf] = self.distorted_wfs[wf]
			# truncate all values that are out of bounds
			if self._channels[wf]['type'] == 'analog':
				if max(wfs[wf]) > hi:
					logging.warning('Clipping waveform {} > {}'.format(
									max(wfs[wf]), hi))
				if min(wfs[wf]) < lo:
					logging.warning('Clipping waveform {} < {}'.format(
									min(wfs[wf]), lo))
				wfs[wf][wfs[wf] > hi] = hi
				wfs[wf][wfs[wf] < lo] = lo
			elif self._channels[wf]['type'] == 'marker':
				wfs[wf][wfs[wf] > lo] = hi
				wfs[wf][wfs[wf] < lo] = lo
		return tvals, wfs

	def normalized_waveforms(self):
		"""
		Returns the final numeric arrays, in which channel-imposed
		restrictions are obeyed (bounds, TTL)
		"""
		tvals, wfs = self.waveforms()

		for wf in wfs:
			hi = self._channels[wf]['high']
			lo = self._channels[wf]['low']

			if self._channels[wf]['type'] == 'analog':
				wfs[wf] = (2.0*wfs[wf] - hi - lo) / (hi - lo)
			elif self._channels[wf]['type'] == 'marker':
				wfs[wf][wfs[wf] > lo] = 1
				wfs[wf][wfs[wf] <= lo] = 0

		return tvals, wfs


	# testing and inspection
	def print_overview(self):
		overview = {}
		overview['length'] = self.length()
		overview['samples'] = self.samples()
		overview['offset'] = self.offset()
		overview['ideal length'] = self.ideal_length()

		overview['pulses'] = {}
		pulses = overview['pulses']
		for p in self.pulses:
			pulses[p] = {}

			pulses[p]['length'] = self.pulse_length(p)
			pulses[p]['samples'] = self.pulse_samples(p)

			for c in self.pulses[p].channels:
				pulses[p][c] = {}
				pulses[p][c]['start time'] = self.pulse_start_time(p, c)
				pulses[p][c]['end time'] = self.pulse_end_time(p, c)
				pulses[p][c]['start sample'] = self.pulse_start_sample(p, c)
				pulses[p][c]['end sample'] = self.pulse_end_sample(p, c)

		pprint.pprint(overview)

# Helper functions, previously part of the element object but moved outside
# to be able to use them in other modules (eg higher level parts of the
# sequencer)


def calculate_time_correction(t0, fixed_point=1e-6):
	return np.round((fixed_point-t0) % fixed_point, decimals=9)


def is_divisible_by_clock(value, clock=1e9):
	'''
	checks if "value" is divisible by the clock period.
	This funciton is needed because of floating point errors
	It performs this by multiplying everything by 1e11 (looking at 0.01ns
	resolution for divisibility)
	'''
	if np.round(value*1e11) % (1/clock*1e11) == 0:
		return True
	else:
		return False

""" Helper for the CS Resources section
"""


import re
from distutils.version import LooseVersion #pylint: disable=no-name-in-module,import-error

from DIRAC                                              import S_OK, S_ERROR, gConfig
from DIRAC.ConfigurationSystem.Client.Helpers.Path      import cfgPath
from DIRAC.Core.Utilities.List                          import uniqueElements, fromChar

__RCSID__ = "$Id$"


gBaseResourcesSection = "/Resources"

def getSites():
  """ Get the list of all the sites defined in the CS
  """
  result = gConfig.getSections( cfgPath( gBaseResourcesSection, 'Sites' ) )
  if not result['OK']:
    return result
  grids = result['Value']
  sites = []
  for grid in grids:
    result = gConfig.getSections( cfgPath( gBaseResourcesSection, 'Sites', grid ) )
    if not result['OK']:
      return result
    sites += result['Value']


  return S_OK( sites )

def getStorageElementSiteMapping( siteList = None ):
  """ Get Storage Element belonging to the given sites
  """
  if not siteList:
    result = getSites()
    if not result['OK']:
      return result
    siteList = result['Value']
  siteDict = {}
  for site in siteList:
    grid = site.split( '.' )[0]
    ses = gConfig.getValue( cfgPath( gBaseResourcesSection, 'Sites', grid, site, 'SE' ), [] )
    if ses:
      siteDict[site] = ses

  return S_OK( siteDict )

def getFTS2ServersForSites( siteList = None ):
  """ get FTSServers for sites

  :param siteList: list of sites
  :type siteList: python:list

  """
  siteList = siteList if siteList else None
  if not siteList:
    siteList = getSites()
    if not siteList["OK"]:
      return siteList
    siteList = siteList["Value"]
  ftsServers = dict()
  defaultServ = gConfig.getValue( cfgPath( gBaseResourcesSection, 'FTSEndpoints/Default', 'FTSEndpoint' ), '' )
  for site in siteList:
    serv = gConfig.getValue( cfgPath( gBaseResourcesSection, "FTSEndpoints/FTS2", site ), defaultServ )
    if serv:
      ftsServers[site] = serv
  return S_OK( ftsServers )


def getFTS3Servers():
  """ get FTSServers for sites
  """

  csPath = cfgPath( gBaseResourcesSection, "FTSEndpoints/FTS3" )
  # We do it in two times to keep the order
  ftsServerNames = gConfig.getOptions( csPath ).get( 'Value', [] )

  ftsServers = []
  for name in ftsServerNames:
    ftsServers.append( gConfig.getValue( cfgPath( csPath, name ) ) )

  return S_OK( ftsServers )


def getSiteTier( site ):
  """
    Return Tier level of the given Site
  """
  result = getSitePath( site )
  if not result['OK']:
    return result
  sitePath = result['Value']
  return S_OK( gConfig.getValue( cfgPath( sitePath, 'MoUTierLevel' ), 2 ) )

def getSitePath( site ):
  """
    Return path to the Site section on CS
  """
  result = getSiteGrid( site )
  if not result['OK']:
    return result
  grid = result['Value']
  return S_OK( cfgPath( gBaseResourcesSection, 'Sites', grid, site ) )

def getSiteGrid( site ):
  """
   Return Grid component from Site Name
  """
  sitetuple = site.split( "." )
  if len( sitetuple ) != 3:
    return S_ERROR( 'Wrong Site Name format' )
  return S_OK( sitetuple[0] )

def getStorageElementOptions( seName ):
  """ Get the CS StorageElementOptions
  """
  storageConfigPath = '/Resources/StorageElements/%s' % seName
  result = gConfig.getOptionsDict( storageConfigPath )
  if not result['OK']:
    return result
  options = result['Value']
  # If the SE is an baseSE or an alias, derefence it
  if 'BaseSE' in options or 'Alias' in options:
    storageConfigPath = '/Resources/StorageElements/%s' % options.get( 'BaseSE', options.get( 'Alias' ) )
    result = gConfig.getOptionsDict( storageConfigPath )
    if not result['OK']:
      return result
    result['Value'].update( options )
    options = result['Value']

  # Help distinguishing storage type
  diskSE = True
  tapeSE = False
  if 'SEType' in options:
    # Type should follow the convention TXDY
    seType = options['SEType']
    diskSE = re.search( 'D[1-9]', seType ) != None
    tapeSE = re.search( 'T[1-9]', seType ) != None
  options['DiskSE'] = diskSE
  options['TapeSE'] = tapeSE

  return S_OK( options )

def getQueue( site, ce, queue ):
  """ Get parameters of the specified queue
  """
  grid = site.split( '.' )[0]
  result = gConfig.getOptionsDict( '/Resources/Sites/%s/%s/CEs/%s' % ( grid, site, ce ) )
  if not result['OK']:
    return result
  resultDict = result['Value']

  for tagFieldName in ( 'Tag', 'RequiredTag' ): 
    Tags = []
    ceTags = resultDict.get( tagFieldName )
    if ceTags:
      Tags = fromChar( ceTags )
    result = gConfig.getOptionsDict( '/Resources/Sites/%s/%s/CEs/%s/Queues/%s' % ( grid, site, ce, queue ) )
    if not result['OK']:
      return result
    resultDict.update( result['Value'] )
    queueTags = resultDict.get( tagFieldName )
    if queueTags:
      queueTags = fromChar( queueTags )
      Tags = list( set( Tags + queueTags ) )
    if Tags:
      resultDict[tagFieldName] = Tags

  resultDict['Queue'] = queue
  return S_OK( resultDict )


def getQueues( siteList = None, ceList = None, ceTypeList = None, community = None, mode = None ):
  """ Get CE/queue options according to the specified selection
  """

  result = gConfig.getSections( '/Resources/Sites' )
  if not result['OK']:
    return result

  resultDict = {}

  grids = result['Value']
  for grid in grids:
    result = gConfig.getSections( '/Resources/Sites/%s' % grid )
    if not result['OK']:
      continue
    sites = result['Value']
    for site in sites:
      if siteList is not None and not site in siteList:
        continue
      if community:
        comList = gConfig.getValue( '/Resources/Sites/%s/%s/VO' % ( grid, site ), [] )
        if comList and not community in comList:
          continue
      siteCEParameters = {}
      result = gConfig.getOptionsDict( '/Resources/Sites/%s/%s/CEs' % ( grid, site ) )
      if result['OK']:
        siteCEParameters = result['Value']
      result = gConfig.getSections( '/Resources/Sites/%s/%s/CEs' % ( grid, site ) )
      if not result['OK']:
        continue
      ces = result['Value']
      for ce in ces:
        if mode:
          ceMode = gConfig.getValue( '/Resources/Sites/%s/%s/CEs/%s/SubmissionMode' % ( grid, site, ce ), 'Direct' )
          if not ceMode or ceMode != mode:
            continue
        if ceTypeList:
          ceType = gConfig.getValue( '/Resources/Sites/%s/%s/CEs/%s/CEType' % ( grid, site, ce ), '' )
          if not ceType or not ceType in ceTypeList:
            continue
        if ceList is not None and not ce in ceList:
          continue
        if community:
          comList = gConfig.getValue( '/Resources/Sites/%s/%s/CEs/%s/VO' % ( grid, site, ce ), [] )
          if comList and not community in comList:
            continue
        ceOptionsDict = dict( siteCEParameters )
        result = gConfig.getOptionsDict( '/Resources/Sites/%s/%s/CEs/%s' % ( grid, site, ce ) )
        if not result['OK']:
          continue
        ceOptionsDict.update( result['Value'] )
        result = gConfig.getSections( '/Resources/Sites/%s/%s/CEs/%s/Queues' % ( grid, site, ce ) )
        if not result['OK']:
          continue
        queues = result['Value']
        for queue in queues:
          if community:
            comList = gConfig.getValue( '/Resources/Sites/%s/%s/CEs/%s/Queues/%s/VO' % ( grid, site, ce, queue ), [] )
            if comList and not community in comList:
              continue
          resultDict.setdefault( site, {} )
          resultDict[site].setdefault( ce, ceOptionsDict )
          resultDict[site][ce].setdefault( 'Queues', {} )
          result = gConfig.getOptionsDict( '/Resources/Sites/%s/%s/CEs/%s/Queues/%s' % ( grid, site, ce, queue ) )
          if not result['OK']:
            continue
          queueOptionsDict = result['Value']
          resultDict[site][ce]['Queues'][queue] = queueOptionsDict

  return S_OK( resultDict )

def getCompatiblePlatforms( originalPlatforms ):
  """ Get a list of platforms compatible with the given list
  """
  if isinstance( originalPlatforms, basestring ):
    platforms = [originalPlatforms]
  else:
    platforms = list( originalPlatforms )

  platforms = list( platform.replace( ' ', '' ) for platform in platforms )

  result = gConfig.getOptionsDict( '/Resources/Computing/OSCompatibility' )
  if not ( result['OK'] and result['Value'] ):
    return S_ERROR( "OS compatibility info not found" )

  platformsDict = dict( ( k, v.replace( ' ', '' ).split( ',' ) ) for k, v in result['Value'].iteritems() )
  for k, v in platformsDict.iteritems():
    if k not in v:
      v.append( k )

  resultList = list( platforms )
  for p in platforms:
    tmpList = platformsDict.get( p, [] )
    for pp in platformsDict:
      if p in platformsDict[pp]:
        tmpList.append( pp )
        tmpList += platformsDict[pp]
    if tmpList:
      resultList += tmpList

  return S_OK( uniqueElements( resultList ) )

def getDIRACPlatform( OS ):
  """ Get standard DIRAC platform(s) compatible with the argument.

      NB: The returned value is a list! ordered, in reverse, using distutils.version.LooseVersion
      In practice the "highest" version (which should be the most "desirable" one is returned first)
  """
  result = gConfig.getOptionsDict( '/Resources/Computing/OSCompatibility' )
  if not ( result['OK'] and result['Value'] ):
    return S_ERROR( "OS compatibility info not found" )

  platformsDict = dict( ( k, v.replace( ' ', '' ).split( ',' ) ) for k, v in result['Value'].iteritems() )
  for k, v in platformsDict.iteritems():
    if k not in v:
      v.append( k )

  # making an OS -> platforms dict
  os2PlatformDict = dict()
  for platform, osItems in platformsDict.iteritems():
    for osItem in osItems:
      if os2PlatformDict.get( osItem ):
        os2PlatformDict[osItem].append( platform )
      else:
        os2PlatformDict[osItem] = [platform]

  if OS not in os2PlatformDict:
    return S_ERROR( 'No compatible DIRAC platform found for %s' % OS )

  platforms = os2PlatformDict[OS]
  platforms.sort( key = LooseVersion, reverse = True )

  return S_OK( platforms )

def getDIRACPlatforms():
  """ just returns list of platforms defined in the CS
  """
  result = gConfig.getOptionsDict( '/Resources/Computing/OSCompatibility' )
  if not ( result['OK'] and result['Value'] ):
    return S_ERROR( "OS compatibility info not found" )
  return S_OK( result['Value'].keys() )

def getCatalogPath( catalogName ):
